let mobileOpen = false;
let userMenuOpen = false;
let desktopCollapsed = false;
let shellInitialized = false;
try { desktopCollapsed = localStorage.getItem('servicehub.sidebar-collapsed') === 'true'; } catch { /* Storage may be disabled. */ }
const expandedSidebarGroups = new Set();

export function toggleDesktopSidebar(collapsed = !desktopCollapsed) {
  desktopCollapsed = collapsed;
  try { localStorage.setItem('servicehub.sidebar-collapsed', String(collapsed)); } catch { /* Preference is optional. */ }
  syncMobileNavigation();
}

export function openSidebarGroup(groupId) {
  toggleDesktopSidebar(false);
  expandedSidebarGroups.add(groupId);
  const panel = document.getElementById(`sidebar-group-${groupId}`) || document.getElementById(`sidebar-subgroup-${groupId}`);
  if (panel) panel.hidden = false;
  document.querySelectorAll(`[data-group="${groupId}"][aria-expanded]`).forEach(button => button.setAttribute('aria-expanded', 'true'));
  document.querySelector(`[data-group="${groupId}"][aria-expanded] svg:last-child`)?.classList.add('rotate-180');
  document.querySelector(`[data-group="${groupId}"][aria-expanded]`)?.focus();
}

export function toggleMobileMenu(open) {
  const wasOpen = mobileOpen;
  mobileOpen = typeof open === 'boolean' ? open : !mobileOpen;
  syncMobileNavigation();
  if (!wasOpen && mobileOpen) document.querySelector('#sidebar [data-action="close-menu"]')?.focus();
  if (wasOpen && !mobileOpen && window.innerWidth < 1024) document.querySelector('[data-action="open-menu"]')?.focus();
}

export function closeUserMenu() {
  userMenuOpen = false;
  const menu = document.getElementById('user-menu-dropdown');
  const btn = document.getElementById('user-menu-button');
  if (menu) {
    menu.classList.add('opacity-0', 'invisible', '-translate-y-1', 'pointer-events-none');
    menu.classList.remove('opacity-100', 'visible', 'translate-y-0', 'pointer-events-auto');
    menu.hidden = true;
  }
  if (btn) {
    btn.setAttribute('aria-expanded', 'false');
    btn.classList.remove('border-primary', 'bg-[#f0f8f2]');
    btn.querySelector('svg:last-child')?.classList.remove('rotate-180');
  }
}

export function toggleUserMenu() {
  userMenuOpen = !userMenuOpen;
  const menu = document.getElementById('user-menu-dropdown');
  const btn = document.getElementById('user-menu-button');
  if (menu) {
    if (userMenuOpen) {
      menu.classList.remove('opacity-0', 'invisible', '-translate-y-1', 'pointer-events-none');
      menu.classList.add('opacity-100', 'visible', 'translate-y-0', 'pointer-events-auto');
      menu.hidden = false;
      menu.querySelector('a, button')?.focus();
    } else {
      menu.classList.add('opacity-0', 'invisible', '-translate-y-1', 'pointer-events-none');
      menu.classList.remove('opacity-100', 'visible', 'translate-y-0', 'pointer-events-auto');
      menu.hidden = true;
      btn?.focus();
    }
  }
  if (btn) {
    btn.setAttribute('aria-expanded', String(userMenuOpen));
    btn.classList.toggle('border-primary', userMenuOpen);
    btn.classList.toggle('bg-[#f0f8f2]', userMenuOpen);
    btn.querySelector('svg:last-child')?.classList.toggle('rotate-180', userMenuOpen);
  }
}

export function expandActiveSidebarGroup(currentModule) {
  const activeGroup = sidebarItems.find((item) =>
    item.type === 'group' &&
    item.children.some((child) => child.module === currentModule || child.children?.some((nested) => nested.module === currentModule))
  );
  if (currentModule === 'waste-collections' || currentModule === 'waste-types') {
    expandedSidebarGroups.add('waste-collections');
  }
  if (activeGroup) {
    expandedSidebarGroups.add(activeGroup.id);
    const activeSubgroup = activeGroup.children.find(
      (child) => child.children?.some((nested) => nested.module === currentModule) || (child.module === currentModule && child.children)
    );
    if (activeSubgroup) expandedSidebarGroups.add(activeSubgroup.module);
  }
}

export function toggleSidebarGroup(groupId) {
  if (expandedSidebarGroups.has(groupId)) {
    expandedSidebarGroups.delete(groupId);
  } else {
    expandedSidebarGroups.add(groupId);
  }
}

export function syncMobileNavigation() {
  const isMobile = window.innerWidth < 1024;
  document.documentElement.classList.toggle('sidebar-collapsed', desktopCollapsed);
  document.querySelectorAll('[data-action="toggle-desktop-sidebar"]').forEach(button => {
    button.setAttribute('aria-expanded', String(!desktopCollapsed));
    button.setAttribute('aria-label', desktopCollapsed ? 'ขยายเมนู' : 'ย่อเมนู');
  });
  document.querySelectorAll('.sidebar-expanded').forEach(element => { element.inert = !isMobile && desktopCollapsed; });
  document.querySelectorAll('.sidebar-rail').forEach(element => { element.inert = isMobile || !desktopCollapsed; });
  document.body.style.overflow = isMobile && mobileOpen ? 'hidden' : '';
  document.querySelectorAll('.app-shell').forEach(element => { element.inert = isMobile && mobileOpen; });
  const sidebarElement = document.getElementById('sidebar');
  const backdrop = document.getElementById('mobile-backdrop');

  if (backdrop) {
    backdrop.classList.toggle('opacity-100', isMobile && mobileOpen);
    backdrop.classList.toggle('pointer-events-auto', isMobile && mobileOpen);
    backdrop.classList.toggle('visible', isMobile && mobileOpen);
    backdrop.classList.toggle('opacity-0', !isMobile || !mobileOpen);
    backdrop.classList.toggle('pointer-events-none', !isMobile || !mobileOpen);
    backdrop.classList.toggle('invisible', !isMobile || !mobileOpen);
  }

  if (sidebarElement) {
    sidebarElement.inert = isMobile && !mobileOpen;
    sidebarElement.setAttribute('aria-hidden', String(!mobileOpen && isMobile));
    if (isMobile) {
      sidebarElement.classList.toggle('-translate-x-full', !mobileOpen);
      sidebarElement.classList.toggle('translate-x-0', mobileOpen);
      sidebarElement.classList.toggle('invisible', !mobileOpen);
      sidebarElement.classList.toggle('pointer-events-none', !mobileOpen);
      sidebarElement.classList.toggle('visible', mobileOpen);
      sidebarElement.classList.toggle('pointer-events-auto', mobileOpen);
    } else {
      sidebarElement.classList.remove('-translate-x-full', 'invisible', 'pointer-events-none');
      sidebarElement.classList.add('translate-x-0', 'visible', 'pointer-events-auto');
    }
  }

  const openBtn = document.querySelector('[data-action="open-menu"]');
  if (openBtn) {
    openBtn.setAttribute('aria-expanded', String(mobileOpen));
  }
}

function sidebarNavItem(item, currentModule) {
  if (item.type === 'link') {
    if (!can(`${item.module}.view`)) return '';
    const active = currentModule === item.module;
    if (!item.children) {
      return `<a href="${moduleHref(item.module)}" class="mb-1 flex min-h-11 items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold leading-5 ${active ? 'nav-active' : 'text-[#657772] hover:bg-[#f4f7f4] hover:text-ink'}" ${active ? 'aria-current="page"' : ''}>${icon(item.icon, 19, 'shrink-0')}<span class="min-w-0 whitespace-normal break-words">${esc(item.label)}</span></a>`;
    }
    const visibleNested = item.children.filter((child) => can(`${child.module}.view`));
    if (!visibleNested.length) {
      return `<a href="${moduleHref(item.module)}" class="mb-1 flex min-h-11 items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold leading-5 ${active ? 'nav-active' : 'text-[#657772] hover:bg-[#f4f7f4] hover:text-ink'}" ${active ? 'aria-current="page"' : ''}>${icon(item.icon, 19, 'shrink-0')}<span class="min-w-0 whitespace-normal break-words">${esc(item.label)}</span></a>`;
    }
    const nestedActive = visibleNested.some((child) => child.module === currentModule);
    const expanded = expandedSidebarGroups.has(item.module);
    return `<div class="mb-1 min-w-0"><div class="flex min-w-0 items-stretch rounded-xl ${active ? 'nav-active' : nestedActive ? 'bg-[#f4f9f5] text-primary-dark' : 'text-[#657772]'}"><a href="${moduleHref(item.module)}" class="flex min-h-11 min-w-0 flex-1 items-center gap-3 rounded-l-xl px-3 py-2.5 text-sm font-semibold leading-5 hover:bg-[#f4f7f4] hover:text-ink" ${active ? 'aria-current="page"' : ''}>${icon(item.icon, 19, 'shrink-0')}<span class="min-w-0 whitespace-normal break-words">${esc(item.label)}</span></a><button type="button" data-action="toggle-sidebar-subgroup" data-group="${item.module}" aria-expanded="${expanded}" aria-controls="sidebar-subgroup-${item.module}" aria-label="${expanded ? 'ปิด' : 'เปิด'}เมนูย่อยของ${esc(item.label)}" class="flex min-h-11 min-w-11 shrink-0 items-center justify-center rounded-r-xl hover:bg-[#f4f7f4]">${icon('chevronDown', 16, `transition-transform ${expanded ? 'rotate-180' : ''}`)}</button></div><div id="sidebar-subgroup-${item.module}" class="ml-5 border-l border-[#dbe9df] pl-3" ${expanded ? '' : 'hidden'}>${visibleNested.map((child) => {
      const selected = currentModule === child.module;
      return `<a href="${child.href || moduleHref(child.module)}" class="my-0.5 flex min-h-11 min-w-0 items-center rounded-xl px-3 py-2.5 text-[13px] font-medium leading-5 ${selected ? 'nav-active' : 'text-[#687b74] hover:bg-[#f4f7f4] hover:text-ink'}" ${selected ? 'aria-current="page"' : ''}><span class="min-w-0 whitespace-normal break-words">${esc(child.label)}</span></a>`;
    }).join('')}</div></div>`;
  }

  const visibleChildren = item.children.filter((child) => can(`${child.module}.view`));
  if (!visibleChildren.length) return '';
  const expanded = expandedSidebarGroups.has(item.id);
  const active = visibleChildren.some((child) => child.module === currentModule || child.children?.some((nested) => nested.module === currentModule && can(`${nested.module}.view`)));
  return `<div class="mb-1">
    <button type="button" data-action="toggle-sidebar-group" data-group="${item.id}" aria-expanded="${expanded}" aria-controls="sidebar-group-${item.id}" class="flex min-h-11 w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold leading-5 ${active ? 'bg-[#f4f9f5] text-primary-dark' : 'text-[#657772] hover:bg-[#f4f7f4] hover:text-ink'}">
      ${icon(item.icon, 19, 'shrink-0')}<span class="min-w-0 flex-1 whitespace-normal break-words">${esc(item.label)}</span>${icon('chevronDown', 16, `shrink-0 transition-transform ${expanded ? 'rotate-180' : ''}`)}
    </button>
    <div id="sidebar-group-${item.id}" class="ml-5 border-l border-[#dbe9df] pl-3" ${expanded ? '' : 'hidden'}>
      ${visibleChildren.map((child) => {
        const selected = currentModule === child.module;
        const href = child.href || moduleHref(child.module);
        if (!child.children) return `<a href="${href}" class="my-0.5 flex min-h-11 items-center rounded-xl px-3 py-2.5 text-[13px] font-medium leading-5 ${selected ? 'nav-active' : 'text-[#687b74] hover:bg-[#f4f7f4] hover:text-ink'}" ${selected ? 'aria-current="page"' : ''}><span class="whitespace-normal break-words">${esc(child.label)}</span></a>`;
        const visibleGrandchildren = child.children.filter((nested) => can(`${nested.module}.view`));
        if (!visibleGrandchildren.length) return `<a href="${href}" class="my-0.5 flex min-h-11 items-center rounded-xl px-3 py-2.5 text-[13px] font-medium leading-5 ${selected ? 'nav-active' : 'text-[#687b74] hover:bg-[#f4f7f4] hover:text-ink'}" ${selected ? 'aria-current="page"' : ''}><span class="whitespace-normal break-words">${esc(child.label)}</span></a>`;
        const subExpanded = expandedSidebarGroups.has(child.module);
        const nestedActive = child.children.some((nested) => nested.module === currentModule);
        return `<div class="my-0.5 min-w-0"><div class="flex min-w-0 items-stretch rounded-xl ${selected ? 'nav-active' : nestedActive ? 'bg-[#f4f9f5] text-primary-dark' : 'text-[#687b74]'}"><a href="${href}" class="flex min-h-11 min-w-0 flex-1 items-center rounded-l-xl px-3 py-2.5 text-[13px] font-medium leading-5 hover:bg-[#f4f7f4] hover:text-ink ${selected ? 'font-semibold' : ''}" ${selected ? 'aria-current="page"' : ''}><span class="min-w-0 whitespace-normal break-words">${esc(child.label)}</span></a><button type="button" data-action="toggle-sidebar-subgroup" data-group="${child.module}" aria-expanded="${subExpanded}" aria-controls="sidebar-subgroup-${child.module}" aria-label="${subExpanded ? 'ปิด' : 'เปิด'}เมนูย่อยของ${esc(child.label)}" class="flex min-h-11 min-w-11 shrink-0 items-center justify-center rounded-r-xl hover:bg-[#f4f7f4]">${icon('chevronDown', 16, `transition-transform ${subExpanded ? 'rotate-180' : ''}`)}</button></div><div id="sidebar-subgroup-${child.module}" class="ml-3 border-l border-[#dbe9df] pl-2" ${subExpanded ? '' : 'hidden'}>${visibleGrandchildren.map((nested) => {
          const nestedSelected = currentModule === nested.module;
          return `<a href="${nested.href || moduleHref(nested.module)}" class="my-0.5 flex min-h-11 min-w-0 items-center rounded-xl px-3 py-2.5 text-[13px] font-medium leading-5 ${nestedSelected ? 'nav-active' : 'text-[#687b74] hover:bg-[#f4f7f4] hover:text-ink'}" ${nestedSelected ? 'aria-current="page"' : ''}><span class="min-w-0 whitespace-normal break-words">${esc(nested.label)}</span></a>`;
        }).join('')}</div></div>`;
      }).join('')}
    </div>
  </div>`;
}

